#!/usr/bin/env python3
"""Embed an operator's gateway CA certificate into include/gateway_root_ca.h.

Run this once per deployment before `pio run`, pointing at the ca.crt
produced by limen-gateway's scripts/provision-local.py (or any CA/cert
that signs your gateway's TLS listener). The generated header is
gitignored — never commit a real one.
"""
from __future__ import print_function

import argparse
import os
import sys


TEMPLATE = """#pragma once

// Generated by scripts/embed_gateway_ca.py — do not edit by hand, and
// never commit this file (it is in .gitignore). Re-run the script if
// your gateway's CA changes.

static const char kGatewayRootCa[] PROGMEM = R"CERT(
{pem}
)CERT";
"""


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("ca_path", help="path to the gateway's CA certificate (PEM)")
    parser.add_argument(
        "--output",
        default=os.path.join(os.path.dirname(__file__), "..", "include", "gateway_root_ca.h"),
    )
    args = parser.parse_args()

    with open(args.ca_path, "r") as handle:
        pem = handle.read().strip()
    if "BEGIN CERTIFICATE" not in pem:
        print("error: {} does not look like a PEM certificate".format(args.ca_path), file=sys.stderr)
        return 1

    output_path = os.path.abspath(args.output)
    with open(output_path, "w") as handle:
        handle.write(TEMPLATE.format(pem=pem))
    print("Wrote {}".format(output_path))
    print("This file is gitignored; re-run this script on every machine that builds the firmware.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
